/** Deterministic, evenly spread selection so no review dominates the silo.
 *  Same slug always yields the same reviews, so the build is reproducible. */
export function reviewsFor(slug: string, n = 3): GoogleReview[] {
  const total = GOOGLE_REVIEWS.length;
  if (total === 0) return [];
  let h = 0;
  for (let i = 0; i < slug.length; i++) h = (h * 31 + slug.charCodeAt(i)) >>> 0;
  const start = h % total;
  const stride = Math.max(1, Math.floor(total / Math.max(1, n)));
  const out: GoogleReview[] = [];
  const seen = new Set<string>();
  for (let i = 0; out.length < Math.min(n, total); i++) {
    const r = GOOGLE_REVIEWS[(start + i * stride + (i % stride)) % total];
    if (seen.has(r.id)) continue;
    seen.add(r.id);
    out.push(r);
  }
  return out;
}

/** Carousel-shaped selection: {quote, name, meta}, still verbatim. */
export function testimonialsFor(slug: string, n = 3) {
  return reviewsFor(slug, n).map((r) => ({
    quote: r.quote,
    name: r.name,
    meta: r.timeAgo ? `Google review, ${r.timeAgo}` : 'Google review',
  }));
}

